let me=null,servers=[],customers=[],page='servers',timer=null,announcementTimer=null,renewalTimer=null,renewalSyncTimer=null,messageTimer=null,messageBadgeTimer=null,renewalExpiresAt=null,renewalClockOffset=0,selectedServer=null,selectedMessageUser=null,messageThreads=[];
