 const stars=Array.from({length:115},makeStar),rocks=Array.from({length:5},()=>({x:random(-.9,.9),y:random(-.55,.55),z:random(.3,1),size:random(2.5,5),spin:random(0,6.28),prev:null})),planets=Array.from({length:2},()=>({x:random(-.8,.8),y:random(-.5,.5),z:random(.55,1),size:random(12,20),phase:random(0,6.28),prev:null}));
 const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches||false;
 let width=0,height=0,dpr=1,last=0;
 function resize(){const r=canvas.getBoundingClientRect(),ratio=Math.min(window.devicePixelRatio||1,1.5),w=Math.max(1,r.width),h=Math.max(1,r.height);if(w!==width||h!==height||ratio!==dpr){width=w;height=h;dpr=ratio;canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}}
 function project(o){return{x:width*.68+o.x/o.z*width*.31,y:height*.52+o.y/o.z*height*.75}}
 function reset(o){o.x=random(-1,1);o.y=random(-.62,.62);o.z=1;o.prev=null;if('phase'in o)o.phase=random(0,6.28)}
 function drawPlanet(o,dt){const p=project(o),r=o.size/o.z;if(p.x+r<-40||p.x-r>width+40||p.y+r<-40||p.y-r>height+40){reset(o);return}const alpha=Math.min(.92,.32+.7*(1-o.z));ctx.save();ctx.globalAlpha=alpha;ctx.translate(p.x,p.y);ctx.rotate(Math.sin(o.phase)*.12);ctx.beginPath();ctx.ellipse(0,r*.18,r*1.42,r*.38,-.12,0,Math.PI*2);ctx.strokeStyle='#d6b46a88';ctx.lineWidth=Math.max(1,r*.045);ctx.stroke();const g=ctx.createRadialGradient(-r*.38,-r*.4,r*.04,0,0,r);g.addColorStop(0,'#d8d7c5');g.addColorStop(.28,'#6b91a4');g.addColorStop(.68,'#344b63');g.addColorStop(1,'#111820');ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();ctx.save();ctx.clip();ctx.globalAlpha*=.55;ctx.strokeStyle='#d3ae61';ctx.lineWidth=Math.max(1,r*.13);for(let i=-2;i<=2;i++){ctx.beginPath();ctx.ellipse(0,i*r*.34,r*.95,r*.13,Math.sin(o.phase+i)*.08,0,Math.PI*2);ctx.stroke()}ctx.restore();ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.strokeStyle='#c7d7d477';ctx.lineWidth=1;ctx.stroke();ctx.restore();if(!reduced)o.z-=.0022*dt;if(o.z<.16)reset(o)}
