 function frame(now){if(!active||!document.body.classList.contains('eve-theme')||page!=='servers'||$('shell').hidden){hyperspaceFrame=0;return}resize();const dt=Math.min(2.5,(now-last||16.7)/16.7);last=now;ctx.clearRect(0,0,width,height);for(const o of stars){const p=project(o);if(o.prev){ctx.beginPath();ctx.moveTo(o.prev.x,o.prev.y);ctx.lineTo(p.x,p.y);ctx.strokeStyle=`hsla(${o.hue},66%,${72+(1-o.z)*20}%,${.14+(1-o.z)*.72})`;ctx.lineWidth=.35+(1-o.z)*1.4;ctx.stroke()}else{ctx.fillStyle=`hsla(${o.hue},72%,80%,.7)`;ctx.fillRect(p.x,p.y,1.2,1.2)}o.prev=p;if(!reduced)o.z-=.008*dt;if(o.z<.1||p.x<-20||p.x>width+20||p.y<-20||p.y>height+20)reset(o)}for(const o of rocks)drawRock(o,dt);for(const o of planets)drawPlanet(o,dt);if(!reduced)hyperspaceFrame=requestAnimationFrame(frame);else hyperspaceFrame=0}
