function applyTheme(theme,persist=false){const fire=theme==='fire',eve=theme==='eve',standard=!fire&&!eve;document.body.classList.toggle('fire-theme',fire);document.body.classList.toggle('eve-theme',eve);$('themeStandard').classList.toggle('active',standard);$('themeFire').classList.toggle('active',fire);$('themeEve').classList.toggle('active',eve);$('themeStandard').setAttribute('aria-pressed',String(standard));$('themeFire').setAttribute('aria-pressed',String(fire));$('themeEve').setAttribute('aria-pressed',String(eve));if(persist){try{localStorage.setItem(THEME_KEY,theme)}catch(e){}}setHyperspaceActive(eve&&!$('shell').hidden&&page==='servers');}
function playHatchSound(){
 try{
  const AudioContextType=window.AudioContext||window.webkitAudioContext;if(!AudioContextType)return;
  const audio=new AudioContextType(),start=audio.currentTime,master=audio.createGain();master.gain.setValueAtTime(.16,start);master.connect(audio.destination);
  if(audio.state==='suspended')audio.resume().catch(()=>{});
  const size=Math.floor(audio.sampleRate*.95),buffer=audio.createBuffer(1,size,audio.sampleRate),samples=buffer.getChannelData(0);for(let i=0;i<size;i++)samples[i]=(Math.random()*2-1)*(1-i/size*.78);
  const air=audio.createBufferSource(),filter=audio.createBiquadFilter(),airGain=audio.createGain();air.buffer=buffer;filter.type='lowpass';filter.frequency.setValueAtTime(2100,start);filter.frequency.exponentialRampToValueAtTime(380,start+.86);airGain.gain.setValueAtTime(.0001,start);airGain.gain.linearRampToValueAtTime(.48,start+.12);airGain.gain.exponentialRampToValueAtTime(.0001,start+.94);air.connect(filter);filter.connect(airGain);airGain.connect(master);air.start(start);air.stop(start+.96);
  const motor=audio.createOscillator(),motorFilter=audio.createBiquadFilter(),motorGain=audio.createGain();motor.type='sawtooth';motor.frequency.setValueAtTime(118,start);motor.frequency.exponentialRampToValueAtTime(48,start+.58);motorFilter.type='lowpass';motorFilter.frequency.value=380;motorGain.gain.setValueAtTime(.0001,start);motorGain.gain.linearRampToValueAtTime(.12,start+.08);motorGain.gain.exponentialRampToValueAtTime(.0001,start+.7);motor.connect(motorFilter);motorFilter.connect(motorGain);motorGain.connect(master);motor.start(start);motor.stop(start+.72);
  const latch=audio.createOscillator(),latchGain=audio.createGain();latch.type='triangle';latch.frequency.setValueAtTime(92,start+.63);latch.frequency.exponentialRampToValueAtTime(38,start+.84);latchGain.gain.setValueAtTime(.0001,start+.63);latchGain.gain.linearRampToValueAtTime(.3,start+.65);latchGain.gain.exponentialRampToValueAtTime(.0001,start+.87);latch.connect(latchGain);latchGain.connect(master);latch.start(start+.63);latch.stop(start+.89);
  setTimeout(()=>audio.close().catch(()=>{}),1300);
 }catch(e){}
}
function chooseTheme(theme){const wasTacticalAmber=document.body.classList.contains('eve-theme');applyTheme(theme,true);if(theme==='eve'&&!wasTacticalAmber)playHatchSound();try{if(sessionStorage.getItem(FIRE_CYCLE_KEY)==='1')sessionStorage.setItem(FIRE_MANUAL_KEY,'1')}catch(e){}}
function fireThresholdExceeded(rows){return rows.some(s=>s.online&&Number.isFinite(Number(s.metrics?.cpu_percent))&&Number(s.metrics.cpu_percent)>50)}
applyTheme(readPreferredTheme());
$('themeStandard').onclick=()=>chooseTheme('standard');$('themeFire').onclick=()=>chooseTheme('fire');$('themeEve').onclick=()=>chooseTheme('eve');
async function api(path,method='GET',data){const r=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json','X-Panel-Entry':panelEntry,'X-CSRF-Token':me?.csrf||''},body:data===undefined?undefined:JSON.stringify(data)});const result=await r.json();if(!r.ok){if(r.status===401&&me)signout();throw Error(result.error||'请求失败')}return result}
function notice(s){$('message').textContent=s}
function signout(){setHyperspaceActive(false);stopNetworkMonitor();$('userForm').reset();$('customerPassword').type='password';me=null;selectedServer=null;selectedMessageUser=null;clearInterval(timer);clearInterval(announcementTimer);clearInterval(renewalTimer);clearInterval(renewalSyncTimer);clearInterval(messageTimer);clearInterval(messageBadgeTimer);$('modal').close();$('shell').hidden=true;$('login').hidden=false}
async function boot(){try{me=await api('me');$('login').hidden=true;$('shell').hidden=false;setHyperspaceActive(document.body.classList.contains('eve-theme')&&page==='servers');$('identity').textContent=me.username+' · '+(me.role==='admin'?'管理员':'客户');document.querySelectorAll('.admin').forEach(x=>x.hidden=me.role!=='admin');$('renewalsMenu').textContent=me.role==='admin'?'◷　续费管理':'◷　服务期限';$('forwardingMenu').textContent=me.role==='admin'?'↗　转发项目':'↗　高性能转发';$('pageTitle').textContent=me.role==='admin'?'服务器概览':'我的服务器';page='servers';await navigate(page);await loadAnnouncements();await refreshMessageBadge();clearInterval(messageBadgeTimer);messageBadgeTimer=setInterval(()=>refreshMessageBadge().catch(()=>{}),10000);clearInterval(announcementTimer);announcementTimer=setInterval(()=>loadAnnouncements().catch(()=>{}),60000);clearInterval(timer);timer=setInterval(()=>{if(page==='servers'&&!$('modal').open)loadServers().catch(e=>notice(e.message));if(page==='ipdns'&&!$('modal').open)refreshIPMonitorStatus().catch(e=>notice(e.message))},5000)}catch(e){signout()}}
$('loginForm').onsubmit=async e=>{e.preventDefault();$('loginError').textContent='';const b=e.submitter;b.disabled=true;try{await api('login','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();await boot()}catch(e){$('loginError').textContent=e.message}finally{b.disabled=false}};
$('logout').onclick=async()=>{try{await api('logout','POST')}catch(e){}signout()};
const names={detectors:'检测点配置',ipdns:'IP 监控与解析',servers:'服务器',renewals:'服务期限',messages:'紧急联系',forwarding:'高性能转发',announcements:'公告管理',users:'客户管理',audit:'操作日志',password:'账号设置',settings:'后台设置'};
async function navigate(target){page=target;setHyperspaceActive(document.body.classList.contains('eve-theme')&&page==='servers');notice('');for(const p of Object.keys(names))$(p+'Page').hidden=p!==page;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('selected',b.dataset.page===page));$('breadcrumb').textContent=page==='renewals'&&me.role==='admin'?'续费管理':page==='forwarding'&&me.role==='admin'?'转发项目':names[page];$('pageTitle').textContent=page==='servers'?(me.role==='admin'?'服务器概览':'我的服务器'):page==='renewals'&&me.role==='admin'?'续费管理':page==='forwarding'&&me.role==='admin'?'转发项目':names[page];$('pageDesc').textContent=page==='servers'?'每一次连接，清晰可见。':page==='messages'?'通过站内消息联系管理员。':page==='forwarding'?(me.role==='admin'?'查看客户的高性能转发申请。':'提交高性能转发开通申请。'):'安全管理你的工作空间。';$('addServer').hidden=page!=='servers'||me.role!=='admin';$('returnMainMenu').hidden=me.role!=='admin'||page!=='messages';if(page!=='renewals'){clearInterval(renewalTimer);clearInterval(renewalSyncTimer);}if(page!=='messages')clearInterval(messageTimer);try{if(page==='servers')await loadServers();if(page==='renewals'){if(me.role==='admin')await loadRenewalAdmin();else await loadOwnSubscription();}if(page==='messages')await openMessages();if(page==='forwarding'){if(me.role==='admin')await loadForwardingAdmin();else await loadForwardingClient();}if(page==='announcements')await loadAnnouncementAdmin();if(page==='users')await loadUsers();if(page==='detectors')await loadDetectors();if(page==='ipdns')await loadIPDNS();if(page==='settings'){const config=await api('settings');$('adminEntry').value=config.admin_path;updateEntryPreview();}if(page==='audit'){const rows=await api('audit');$('auditRows').innerHTML=rows.map(r=>`<div class="audit-row">${esc(r.action)}<small>${esc(r.username||'系统')} · ${new Date(r.created*1000).toLocaleString()}</small></div>`).join('')||'<p>暂无操作记录</p>'}}catch(e){notice(e.message)}}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('returnMainMenu').onclick=()=>{selectedServer=null;navigate('servers');};$('refresh').onclick=()=>navigate(page);
async function refreshMessageBadge(){if(!me)return;const data=await api('messages/unread');const badge=$('messagesBadge');badge.textContent=data.unread>99?'99+':String(data.unread);badge.hidden=!data.unread;}
function renderMessageThreads(){const host=$('messageThreads');host.innerHTML=messageThreads.map(t=>`<button type="button" class="wechat-thread ${Number(t.user_id)===Number(selectedMessageUser)?'active':''}" data-message-user="${t.user_id}"><span class="wechat-avatar">${esc((t.username||'?').slice(0,1).toUpperCase())}</span><span class="wechat-thread-copy"><strong>${esc(t.username)}</strong><small>${esc(t.last_content||'开始紧急联系')}</small></span>${t.unread?`<i class="wechat-unread">${t.unread>99?'99+':t.unread}</i>`:''}</button>`).join('')||'<p class="wechat-empty">暂无客户账号。</p>';host.querySelectorAll('[data-message-user]').forEach(b=>b.onclick=()=>{selectedMessageUser=Number(b.dataset.messageUser);loadMessageConversation(true).catch(e=>notice(e.message));});}
async function openMessages(){clearInterval(messageTimer);$('messageContacts').hidden=me.role!=='admin';$('messagesPage').classList.toggle('client-messages',me.role==='client');if(me.role==='client'){selectedMessageUser=me.id;$('chatHeader').innerHTML=`<span class="wechat-avatar">管</span><span><strong>管理员</strong><small>紧急联系 · 站内消息</small></span>`;}else if(!selectedMessageUser){selectedMessageUser=null;}
 await loadMessagesPage();messageTimer=setInterval(()=>{if(page==='messages')loadMessagesPage().catch(()=>{});},3000);}
async function loadMessagesPage(){if(me.role==='admin'){messageThreads=await api('messages/threads');if(!messageThreads.some(t=>Number(t.user_id)===Number(selectedMessageUser)))selectedMessageUser=messageThreads[0]?Number(messageThreads[0].user_id):null;renderMessageThreads();if(!selectedMessageUser){$('chatMessages').innerHTML='<div class="wechat-empty-state"><span>✉</span><strong>选择一位客户</strong><small>收到的消息和回复会显示在这里。</small></div>';return;}}await loadMessageConversation(false);}
async function loadMessageConversation(scroll=true){const uid=selectedMessageUser;if(!uid)return;const box=$('chatMessages'),nearBottom=scroll||box.scrollHeight-box.scrollTop-box.clientHeight<90;const data=await api('messages/threads/'+uid);if(page!=='messages'||Number(uid)!==Number(selectedMessageUser))return;if(me.role==='admin')$('chatHeader').innerHTML=`<span class="wechat-avatar">${esc((data.username||'?').slice(0,1).toUpperCase())}</span><span><strong>${esc(data.username)}</strong><small>紧急联系 · 客户站内消息</small></span>`;box.innerHTML=data.messages.map(m=>`<div class="wechat-message ${Number(m.sender_id)===Number(me.id)?'mine':'theirs'}"><span class="wechat-message-name">${esc(m.sender_name)}</span><div class="wechat-bubble">${esc(m.content).replace(/\n/g,'<br>')}</div><time>${new Date(m.created*1000).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</time></div>`).join('')||'<div class="wechat-empty-state"><span>👋</span><strong>还没有消息</strong><small>在下方发送一条消息，开始联系管理员。</small></div>';if(nearBottom)box.scrollTop=box.scrollHeight;if(me.role==='admin'){messageThreads=await api('messages/threads');renderMessageThreads();}await refreshMessageBadge();}
$('messageForm').onsubmit=async e=>{e.preventDefault();const input=$('messageInput'),button=e.submitter,content=input.value;if(!selectedMessageUser||!content.trim())return;button.disabled=true;try{await api('messages/threads/'+selectedMessageUser,'POST',{content});input.value='';await loadMessageConversation(true);}catch(err){notice(err.message);}finally{button.disabled=false;input.focus();}};
function formatForwardingTime(stamp){return stamp?new Date(stamp*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—';}
async function loadForwardingClient(){const client=$('forwardingClientView'),admin=$('forwardingAdminView');client.hidden=false;admin.hidden=true;const button=$('submitForwardingRequest'),state=$('forwardingRequestState');button.disabled=true;try{const request=await api('forwarding-request');if(request.id){button.textContent='申请已提交';button.disabled=true;state.textContent='已于 '+formatForwardingTime(request.created)+' 提交，等待管理员处理。';state.classList.add('submitted');}else{button.textContent='提交申请管理员开通';button.disabled=false;state.textContent='尚未提交申请。';state.classList.remove('submitted');}}catch(e){button.disabled=true;state.textContent='无法读取申请状态：'+e.message;}}
async function loadForwardingAdmin(){const client=$('forwardingClientView'),admin=$('forwardingAdminView');client.hidden=true;admin.hidden=false;const rows=await api('admin/forwarding-requests');$('forwardingRequestCount').textContent=rows.length+' 条申请';$('forwardingRequestRows').innerHTML=rows.map(r=>`<tr><td>${esc(r.username)}</td><td>${esc(formatForwardingTime(r.created))}</td></tr>`).join('')||'<tr><td colspan="2" class="forwarding-no-requests">暂无转发申请。</td></tr>';}
$('forwardingRequestForm').onsubmit=async e=>{e.preventDefault();const button=$('submitForwardingRequest'),state=$('forwardingRequestState');button.disabled=true;state.textContent='正在提交申请…';try{await api('forwarding-request','POST',{});await loadForwardingClient();notice('转发申请已提交');}catch(err){button.disabled=false;state.textContent='提交失败：'+err.message;}};
function value(v,suffix=''){return v===null||v===undefined?'—':Number(v).toLocaleString()+suffix}
function metric(s,key){return s.online?value(s.metrics?.[key]):'—'}
function scopedServers(){return selectedServer===null?servers:servers.filter(s=>s.id===selectedServer);}
function resourceMemory(s){const used=s.online?s.metrics?.memory_used:null,total=s.online?s.metrics?.memory_total:null;return used==null||total==null?'内存 — / —':`内存 ${formatBytes(used)} / ${formatBytes(total)}`;}
function resourceCPU(s){return s.online&&Number.isInteger(s.metrics?.cpu_count)?`CPU ${s.metrics.cpu_count} vCPU`:'CPU — vCPU';}
function isCPUHot(s){return percentValue(s,'cpu_percent')>50;}
function percentValue(s,key){const raw=s.online?s.metrics?.[key]:null;const n=Number(raw);return raw===null||raw===undefined||raw===''||!Number.isFinite(n)?null:Math.max(0,Math.min(100,n));}
function resourceGauge(s,key,label,spec,color){const percentKey=key+'_percent',current=percentValue(s,percentKey),prior=percentValue({online:!!s.online,metrics:previousMetrics.get(s.id)||{}},percentKey),start=prior??current??0,target=current??0;return `<button class="metric-gauge metric-link" data-metric="${key}" data-server="${s.id}" aria-label="查看 ${esc(s.name)} ${label} 动态监控"><span class="mini-gauge-ring ${key==='cpu'&&current!==null&&current>50?'burning-gauge':''}" style="--gauge-color:${color};--gauge-value:${start}%" data-gauge-target="${target}"><span>${current===null?'—':Math.round(current)+'%'}</span></span><span class="gauge-copy"><strong>${label}</strong><small>${esc(spec)}</small></span></button>`;}
function networkLevel(rx,tx){const max=Math.max(Number(rx)||0,Number(tx)||0);return max>0?{rx:Math.max(0,Math.min(100,Number(rx||0)/max*100)),tx:Math.max(0,Math.min(100,Number(tx||0)/max*100))}:{rx:0,tx:0};}
function networkMeters(s){const m=s.online?s.metrics||{}:{},old=previousMetrics.get(s.id)||{},cur=networkLevel(m.rx_bps,m.tx_bps),prior=networkLevel(old.rx_bps,old.tx_bps),rxStart=old.rx_bps==null?cur.rx:prior.rx,txStart=old.tx_bps==null?cur.tx:prior.tx;return `<div class="network-meter"><button class="metric-link network-rate" data-metric="network" data-server="${s.id}" aria-label="查看 ${esc(s.name)} 网络动态监控"><span>↓ <b>${formatRate(s.online?m.rx_bps:null)}</b></span><i><em style="width:${rxStart}%" data-meter-target="${cur.rx}"></em></i></button><button class="metric-link network-rate" data-metric="network" data-server="${s.id}" aria-label="查看 ${esc(s.name)} 网络动态监控"><span>↑ <b>${formatRate(s.online?m.tx_bps:null)}</b></span><i><em style="width:${txStart}%" data-meter-target="${cur.tx}"></em></i></button></div>`;}
function connectionCounters(s){return `<div class="connection-counters"><button class="metric-link connection-main" data-metric="tcp" data-server="${s.id}"><span>TCP</span><strong>${metric(s,'tcp')}</strong></button><button class="metric-link connection-secondary" data-metric="udp" data-server="${s.id}"><span>UDP</span><strong>${metric(s,'udp')}</strong></button></div>`;}
function animateMetricTransitions(){if(typeof requestAnimationFrame!=='function')return;requestAnimationFrame(()=>{document.querySelectorAll('[data-gauge-target]').forEach(el=>el.style.setProperty('--gauge-value',Math.max(0,Math.min(100,Number(el.dataset.gaugeTarget)||0))+'%'));document.querySelectorAll('[data-meter-target]').forEach(el=>el.style.width=Math.max(0,Math.min(100,Number(el.dataset.meterTarget)||0))+'%');});}
function totalTraffic(t,period){const rx=t?.[period+'_rx'],tx=t?.[period+'_tx'];return rx==null||tx==null?null:rx+tx;}
function sum(key){const v=scopedServers().filter(s=>s.online&&s.metrics?.[key]!=null);return v.length?value(v.reduce((n,s)=>n+s.metrics[key],0)):'—'}
async function loadServers(){const incoming=await api('servers');previousMetrics=new Map(servers.map(s=>[s.id,s.online?s.metrics||{}:{}]));servers=incoming;if(selectedServer!==null&&!servers.some(s=>s.id===selectedServer))selectedServer=null;const fire=fireThresholdExceeded(incoming);let justTriggered=false;try{const active=sessionStorage.getItem(FIRE_CYCLE_KEY)==='1',manual=sessionStorage.getItem(FIRE_MANUAL_KEY)==='1';if(fire){if(!active){sessionStorage.setItem(FIRE_CYCLE_KEY,'1');sessionStorage.removeItem(FIRE_MANUAL_KEY);applyTheme('fire');justTriggered=true}else if(!manual)applyTheme('fire')}else{sessionStorage.removeItem(FIRE_CYCLE_KEY);sessionStorage.removeItem(FIRE_MANUAL_KEY);applyTheme(readPreferredTheme())}}catch(e){if(fire)applyTheme('fire')}renderSummary();renderServers();if(justTriggered)setTimeout(()=>location.reload(),350);}
function renderSummary(){const scope=scopedServers();$('fireNotice').hidden=!fireThresholdExceeded(servers)||!document.body.classList.contains('fire-theme');$('total').textContent=scope.length;$('online').textContent=scope.filter(s=>s.online).length;$('tcp').textContent=sum('tcp');$('udp').textContent=sum('udp');$('rxRate').textContent=rateSum('rx_bps');$('txRate').textContent=rateSum('tx_bps');$('monthRx').textContent=trafficSum('month_rx');$('monthTx').textContent=trafficSum('month_tx');const totals=scope.map(s=>totalTraffic(s.traffic,'today')).filter(n=>n!==null);$('todayTotal').textContent=formatBytes(totals.length?totals.reduce((a,b)=>a+b,0):null);const node=scope[0];$('summaryScope').textContent=selectedServer===null?'全部服务器汇总':('当前 VPS：'+(node?.name||''));$('clearServerSelection').hidden=selectedServer===null;document.querySelectorAll('[data-scope-note]').forEach(n=>n.textContent=selectedServer===null?n.dataset.scopeNote:'当前 VPS · 北京时间');renderEveCockpit(scope);}
function renderEveCockpit(scope=scopedServers()){const online=scope.filter(s=>s.online),average=key=>{const values=online.map(s=>Number(s.metrics?.[key])).filter(Number.isFinite);return values.length?values.reduce((a,b)=>a+b,0)/values.length:null;},cpu=average('cpu_percent'),memory=average('memory_percent'),memoryPairs=online.map(s=>[Number(s.metrics?.memory_used),Number(s.metrics?.memory_total)]).filter(v=>v.every(Number.isFinite)),used=memoryPairs.length?memoryPairs.reduce((n,v)=>n+v[0],0):null,total=memoryPairs.length?memoryPairs.reduce((n,v)=>n+v[1],0):null,cores=online.map(s=>Number(s.metrics?.cpu_count)).filter(Number.isFinite).reduce((a,b)=>a+b,0);$('eveCpuValue').textContent=cpu===null?'—':Math.round(cpu)+'%';$('eveCpuDial').style.setProperty('--eve-value',(cpu||0)+'%');$('eveCpuDial').style.setProperty('--eve-angle',(-135+Math.max(0,Math.min(100,cpu||0))*2.7)+'deg');$('eveMemoryValue').textContent=memory===null?'—':Math.round(memory)+'%';$('eveMemoryDial').style.setProperty('--eve-value',(memory||0)+'%');$('eveMemoryDial').style.setProperty('--eve-angle',(-135+Math.max(0,Math.min(100,memory||0))*2.7)+'deg');$('eveOnlineNodes').textContent=online.length+' / '+scope.length;$('eveCoreTotal').textContent=cores?cores+' vCPU':'—';$('eveMemoryUsed').textContent=used===null||total===null?'—':formatBytes(used)+' / '+formatBytes(total);$('eveMemoryNodes').textContent=memoryPairs.length;$('eveRxRate').textContent=rateSum('rx_bps');$('eveTxRate').textContent=rateSum('tx_bps');$('eveTcp').textContent=sum('tcp');$('eveUdp').textContent=sum('udp');const totals=scope.map(s=>totalTraffic(s.traffic,'today')).filter(n=>n!==null);$('eveTodayTraffic').textContent=formatBytes(totals.length?totals.reduce((a,b)=>a+b,0):null);}
function selectServer(id){selectedServer=selectedServer===id?null:id;renderSummary();renderServers();}
$('clearServerSelection').onclick=()=>{selectedServer=null;renderSummary();renderServers();};

function renderServers(){const q=$('search').value.toLowerCase();$('serverRows').innerHTML=servers.filter(s=>s.name.toLowerCase().includes(q)).map(s=>`<tr data-row-server="${s.id}" class="${selectedServer===s.id?'selected-server ':''}${isCPUHot(s)?'fire-alert-row':''}"><td><button class="server-select" data-select-server="${s.id}" aria-pressed="${selectedServer===s.id}">${esc(s.name)}</button><span class="muted">${esc(s.metrics?.os||'等待首次上报')}</span>${isCPUHot(s)?'<span class="fire-embers" aria-hidden="true"></span>':''}<span class="muted">${me.role==='admin'?' / '+esc(s.owner||'未分配'):''}</span></td><td class="public-ip-cell">${publicIPMarkup(s)}</td><td><span class="badge ${s.online?'online':''}">${s.online?'在线':s.seen?'离线':'待接入'}</span></td><td class="metrics"><div class="resource-stack">${resourceGauge(s,'cpu','CPU',resourceCPU(s),'#2878f0')}${resourceGauge(s,'memory','内存',resourceMemory(s),'#8b6df2')}</div><span class="disk-label">磁盘 ${metric(s,'disk_percent')}%</span></td><td class="metrics">${networkMeters(s)}</td><td class="metrics"><b class="daily-total">当日总流量 ${formatBytes(totalTraffic(s.traffic,'today'))}</b><br>今日 ↓ ${formatBytes(s.traffic?.today_rx)} / ↑ ${formatBytes(s.traffic?.today_tx)}<br>本月 ↓ ${formatBytes(s.traffic?.month_rx)} / ↑ ${formatBytes(s.traffic?.month_tx)}</td><td class="metrics">${connectionCounters(s)}</td><td>${formatUptime(s)}</td><td>${s.seen?new Date(s.seen*1000).toLocaleTimeString():'—'}</td><td><div class="server-actions"><button data-detail="${s.id}">详情</button><button data-ip-history="${s.id}">历史 IP</button>${me.role==='admin'?`<button data-enroll="${s.id}">对接命令</button>`:''}<button data-reboot="${s.id}" class="reboot-button" ${canReboot(s)?'':'disabled'} title="${rebootReason(s)}">重启 VPS</button></div><span class="muted">${commandLabel(s.last_command)}</span></td></tr>`).join('');$('empty').hidden=!!servers.length;$('emptyText').textContent=me.role==='admin'?'点击“添加服务器”，获取客户端接入方式。':'管理员分配服务器后，将在这里显示。';animateMetricTransitions();$('serverRows').querySelectorAll('[data-select-server]').forEach(b=>b.onclick=()=>selectServer(Number(b.dataset.selectServer)));$('serverRows').querySelectorAll('[data-row-server]').forEach(row=>{const labels=['服务器','公网 IP','状态','CPU / 内存 / 磁盘','当前带宽','流量统计','TCP / UDP','运行时间','最后上报','操作'];Array.from(row.children).forEach((cell,i)=>cell.dataset.label=labels[i]);row.onclick=e=>{if(!e.target.closest('button,a,input,select')&&!window.getSelection()?.toString())selectServer(Number(row.dataset.rowServer));};});$('serverRows').querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>openMetricWindow(Number(b.dataset.server),b.dataset.metric));$('serverRows').querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(Number(b.dataset.detail)));$('serverRows').querySelectorAll('[data-ip-history]').forEach(b=>b.onclick=()=>showIPHistory(Number(b.dataset.ipHistory)));$('serverRows').querySelectorAll('[data-enroll]').forEach(b=>b.onclick=()=>generateInstallCommand(Number(b.dataset.enroll)));$('serverRows').querySelectorAll('[data-reboot]').forEach(b=>b.onclick=()=>rebootServer(Number(b.dataset.reboot)))}
$('search').oninput=renderServers;
function renderAnnouncementTicker(rows){const bar=$('announcementTicker'),track=$('announcementTrack');if(!rows.length){bar.hidden=true;track.replaceChildren();return;}const text=rows.map(a=>`${a.title}：${a.content.replace(/\s+/g,' ')}`).join('　　✦　　');track.innerHTML=`<span>${esc(text)}</span><span aria-hidden="true">${esc(text)}</span>`;bar.hidden=false;}
async function loadAnnouncements(){const rows=await api('announcements');renderAnnouncementTicker(rows);}
let adminAnnouncements=[];
function renderAnnouncementAdmin(){const host=$('announcementAdminRows');host.innerHTML=adminAnnouncements.map(a=>`<div class="announcement-admin-item"><div class="announcement-admin-item-head"><div><strong>${esc(a.title)}</strong><span class="announcement-status ${a.published?'published':'draft'}">${a.published?'已发布':'未发布'}</span></div><small>${new Date(a.updated*1000).toLocaleString()}</small></div><p>${esc(a.content)}</p><div class="announcement-admin-actions"><button type="button" data-edit-announcement="${a.id}">编辑</button><button type="button" data-toggle-announcement="${a.id}">${a.published?'撤回':'重新发布'}</button><button type="button" class="danger" data-delete-announcement="${a.id}">删除</button></div></div>`).join('')||'<p class="announcement-empty">暂时还没有公告，使用上方表单发布第一条公告。</p>';host.querySelectorAll('[data-edit-announcement]').forEach(b=>b.onclick=()=>editAnnouncement(Number(b.dataset.editAnnouncement)));host.querySelectorAll('[data-toggle-announcement]').forEach(b=>b.onclick=()=>toggleAnnouncement(Number(b.dataset.toggleAnnouncement)));host.querySelectorAll('[data-delete-announcement]').forEach(b=>b.onclick=()=>deleteAnnouncement(Number(b.dataset.deleteAnnouncement)));}
async function loadAnnouncementAdmin(){adminAnnouncements=await api('admin/announcements');renderAnnouncementAdmin();}
function renewalNow(){return Date.now()/1000+renewalClockOffset;}
function renewalState(expiresAt){if(expiresAt==null)return 'unset';return expiresAt>renewalNow()?'active':'expired';}
function renewalStatusLabel(expiresAt){const state=renewalState(expiresAt);if(state==='unset')return '未设置';if(state==='expired')return '已到期';const left=expiresAt-renewalNow();return left<=7*86400?'即将到期':'服务正常';}
function renderRenewalCountdown(data){const card=$('renewalCard');card.classList.remove('renewal-soon','renewal-expired','renewal-unset');const status=$('renewalStatus');renewalExpiresAt=data.expires_at;renewalClockOffset=Number.isFinite(data.server_now)?data.server_now-Date.now()/1000:0;if(renewalExpiresAt==null){card.classList.add('renewal-unset');status.textContent='未设置';status.className='renewal-status renewal-unset-status';$('renewalExpiry').textContent='尚未设置';$('renewalCycle').textContent='续费周期：—';$('renewalRemaining').textContent='—';$('renewalRemainingHint').textContent='请联系管理员设置服务期限';$('renewalProgressLabel').textContent='等待设置';$('renewalProgress').style.width='0%';$('renewalIntro').textContent='管理员尚未设置服务到期时间。';$('renewalHelp').textContent='设置完成后，这里会显示到期日期、续费周期和动态剩余时间。';clearInterval(renewalTimer);return;}const expiryDate=new Date(renewalExpiresAt*1000);$('renewalExpiry').textContent=expiryDate.toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});$('renewalCycle').textContent=`续费周期：每 ${data.cycle_months} 个自然月`;$('renewalIntro').textContent='到期时间按北京时间计算，页面会实时更新剩余时间。';$('renewalHelp').textContent='如需续费或对到期时间有疑问，请联系管理员。';clearInterval(renewalTimer);const update=()=>{const now=renewalNow(),left=Math.max(0,renewalExpiresAt-now),days=Math.floor(left/86400),hours=Math.floor(left%86400/3600),minutes=Math.floor(left%3600/60),seconds=Math.floor(left%60);const state=renewalState(renewalExpiresAt);card.classList.toggle('renewal-expired',state==='expired');card.classList.toggle('renewal-soon',state==='active'&&left<=7*86400);status.textContent=renewalStatusLabel(renewalExpiresAt);status.className='renewal-status '+(state==='expired'?'renewal-expired-status':state==='active'&&left<=7*86400?'renewal-soon-status':'renewal-active-status');$('renewalRemaining').textContent=state==='expired'?'已到期':`${days} 天 ${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`;$('renewalRemainingHint').textContent=state==='expired'?'请联系管理员办理续期':'剩余 天 · 时 · 分 · 秒';const total=Math.max(1,renewalExpiresAt-(data.starts_at||now)),elapsed=Math.max(0,Math.min(1,(now-(data.starts_at||now))/total));$('renewalProgress').style.width=(elapsed*100).toFixed(1)+'%';$('renewalProgressLabel').textContent=state==='expired'?'周期已结束':`已使用 ${Math.round(elapsed*100)}%`;};update();renewalTimer=setInterval(update,1000);}
async function loadOwnSubscription(){$('renewalClientView').hidden=false;$('renewalAdminView').hidden=true;try{renderRenewalCountdown(await api('subscription'));clearInterval(renewalSyncTimer);renewalSyncTimer=setInterval(()=>{if(page==='renewals')api('subscription').then(renderRenewalCountdown).catch(()=>{});},60000);}catch(e){notice(e.message);}}
async function loadRenewalAdmin(){clearInterval(renewalTimer);$('renewalClientView').hidden=true;$('renewalAdminView').hidden=false;customers=await api('users');const rows=customers.filter(u=>u.role==='client');$('renewalAdminRows').innerHTML=rows.map(u=>{const expiry=u.expires_on?new Date(u.expires_on+'T23:59:59+08:00'):null;const state=u.expires_on?expiry.getTime()>Date.now()?'服务正常':'已到期':'未设置';return `<tr><td>${esc(u.username)}</td><td>${u.expires_on?esc(u.expires_on)+' 23:59':'—'}</td><td>${u.cycle_months?`每 ${u.cycle_months} 个自然月`:'—'}</td><td><span class="renewal-admin-state ${state==='已到期'?'expired':state==='服务正常'?'active':'unset'}">${state}</span></td><td><button type="button" data-manage-renewal="${u.id}">${u.expires_on?'设置／续期':'设置期限'}</button></td></tr>`;}).join('')||'<tr><td colspan="5">暂无客户账号。</td></tr>';$('renewalAdminRows').querySelectorAll('[data-manage-renewal]').forEach(b=>b.onclick=()=>manageClientRenewal(Number(b.dataset.manageRenewal)));}
$('refreshRenewals').onclick=()=>loadRenewalAdmin().catch(e=>notice(e.message));
async function manageClientRenewal(id){const customer=customers.find(c=>c.id===id);if(!customer)return;try{const data=await api('users/'+id+'/subscription');modal(`<h2>设置 ${esc(customer.username)} 的服务期限</h2><p>到期日期按北京时间当天 23:59:59 为有效期终点。周期续期按自然月计算；若目标月份没有对应日期，则取该月最后一天。</p><form id="renewalForm"><label>到期日期<input id="renewalEditDate" type="date" required></label><label>续费周期<select id="renewalEditMonths"><option value="1">1 个自然月</option><option value="2">2 个自然月</option><option value="3">3 个自然月</option><option value="6">6 个自然月</option><option value="12">12 个自然月</option></select></label><div class="detail-actions"><button class="primary">保存期限</button><button type="button" id="renewNow" ${data.expires_on?'':'disabled'}>按周期续期</button><button type="button" id="clearRenewal" class="danger" ${data.expires_on?'':'disabled'}>清除期限</button></div><p id="renewalFormError" role="status"></p></form>`);if(data.expires_on)$('renewalEditDate').value=data.expires_on;$('renewalEditMonths').value=String(data.cycle_months||1);$('renewalForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await api('users/'+id+'/subscription','PATCH',{expires_on:$('renewalEditDate').value,cycle_months:Number($('renewalEditMonths').value)});$('modal').close();await loadRenewalAdmin();notice('客户服务期限已保存');}catch(e){$('renewalFormError').textContent=e.message;}finally{b.disabled=false;}};$('renewNow').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{await api('users/'+id+'/subscription/renew','POST',{});$('modal').close();await loadRenewalAdmin();notice('已按自然月周期续期');}catch(e){$('renewalFormError').textContent=e.message;b.disabled=false;}};$('clearRenewal').onclick=async e=>{if(!confirm('确定清除该客户的服务期限吗？'))return;const b=e.currentTarget;b.disabled=true;try{await api('users/'+id+'/subscription','DELETE');$('modal').close();await loadRenewalAdmin();notice('服务期限已清除');}catch(e){$('renewalFormError').textContent=e.message;b.disabled=false;}};}catch(e){notice(e.message);}}
function resetAnnouncementEditor(){const form=$('announcementForm');form.reset();$('announcementId').value='';$('saveAnnouncement').textContent='发布公告';$('cancelAnnouncementEdit').hidden=true;}
function editAnnouncement(id){const a=adminAnnouncements.find(x=>x.id===id);if(!a)return;$('announcementId').value=a.id;$('announcementTitle').value=a.title;$('announcementContent').value=a.content;$('announcementPublished').checked=!!a.published;$('saveAnnouncement').textContent='保存修改';$('cancelAnnouncementEdit').hidden=false;$('announcementForm').scrollIntoView({behavior:'smooth',block:'center'});}
async function toggleAnnouncement(id){const a=adminAnnouncements.find(x=>x.id===id);if(!a)return;try{await api('announcements/'+id,'PATCH',{published:!a.published});await loadAnnouncementAdmin();await loadAnnouncements();notice(a.published?'公告已撤回':'公告已重新发布');}catch(e){notice(e.message);}}
async function deleteAnnouncement(id){const a=adminAnnouncements.find(x=>x.id===id);if(!a||!confirm('确定删除公告“'+a.title+'”吗？'))return;try{await api('announcements/'+id,'DELETE');await loadAnnouncementAdmin();await loadAnnouncements();notice('公告已删除');}catch(e){notice(e.message);}}
$('announcementForm').onsubmit=async e=>{e.preventDefault();const id=$('announcementId').value;const data={title:$('announcementTitle').value,content:$('announcementContent').value,published:$('announcementPublished').checked};const button=$('saveAnnouncement');button.disabled=true;try{await api(id?'announcements/'+id:'announcements',id?'PATCH':'POST',data);resetAnnouncementEditor();await loadAnnouncementAdmin();await loadAnnouncements();notice(id?'公告已更新':'公告已发布');}catch(e){notice(e.message);}finally{button.disabled=false;}};
$('cancelAnnouncementEdit').onclick=resetAnnouncementEditor;

async function loadUsers(){customers=await api('users');$('userRows').innerHTML=customers.map(u=>`<tr><td>#${u.id}</td><td>${esc(u.username)}</td><td>${u.role==='admin'?'管理员':'客户'}</td><td><div class="customer-actions"><button type="button" data-copy-account="${u.id}">复制账号</button>${u.role==='client'?`<button type="button" data-copy-customer="${u.id}">复制客户信息</button><button type="button" data-view-secret="${u.id}">查看密码</button><button type="button" data-copy-secret="${u.id}">复制密码</button><button type="button" data-edit-customer="${u.id}">修改账号／密码</button><button type="button" data-assign-customer="${u.id}">分配服务器</button>`:''}</div></td></tr>`).join('');$('userRows').querySelectorAll('[data-copy-account]').forEach(b=>b.onclick=()=>copyCustomerValue(Number(b.dataset.copyAccount),false));$('userRows').querySelectorAll('[data-copy-customer]').forEach(b=>b.onclick=()=>copyCustomerInfo(Number(b.dataset.copyCustomer)));$('userRows').querySelectorAll('[data-copy-secret]').forEach(b=>b.onclick=()=>copyCustomerValue(Number(b.dataset.copySecret),true));$('userRows').querySelectorAll('[data-view-secret]').forEach(b=>b.onclick=()=>viewCustomerPassword(Number(b.dataset.viewSecret)));$('userRows').querySelectorAll('[data-edit-customer]').forEach(b=>b.onclick=()=>editCustomer(Number(b.dataset.editCustomer)));$('userRows').querySelectorAll('[data-assign-customer]').forEach(b=>b.onclick=()=>assignCustomerServers(Number(b.dataset.assignCustomer)));}
$('userForm').onsubmit=async e=>{e.preventDefault();try{const credentials=Object.fromEntries(new FormData(e.target));await api('users','POST',credentials);e.target.reset();$('customerPassword').type='password';$('passwordHint').textContent='可手动填写，或生成 20 位随机密码。';await loadUsers();notice('客户已创建')}catch(e){notice(e.message)}};
$('passwordForm').onsubmit=async e=>{e.preventDefault();try{await api('password','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();signout();$('loginError').textContent='密码已修改，请重新登录'}catch(e){notice(e.message)}};
$('closeModal').onclick=()=>$('modal').close();
function modal(html){stopNetworkMonitor();ipHistoryView++;$('modalBody').innerHTML=html;if(!$('modal').open)$('modal').showModal()}
$('addServer').onclick=()=>{modal('<h2>添加服务器</h2><p>创建后生成独立采集密钥，仅显示一次。</p><form id="serverForm"><label>服务器名称<input name="name" maxlength="64" required placeholder="例如 HK-01"></label><button class="primary">创建并获取接入方式</button><p id="formError"></p></form>');$('serverForm').onsubmit=async e=>{e.preventDefault();try{const r=await api('servers','POST',Object.fromEntries(new FormData(e.target)));enrollment(r.token,r.ticket);await loadServers()}catch(e){$('formError').textContent=e.message}}};
function shellQuote(text){return "'"+String(text).replace(/'/g,"'\"'\"'")+"'";}
function buildInstallCommand(ticket){const script=['set -e','if ! command -v curl >/dev/null 2>&1; then apt-get update; apt-get install -y curl ca-certificates; fi','file=$(mktemp)',`trap 'rm -f "$file"' EXIT`,'curl -fsS --proto "=https" --tlsv1.2 "${PANEL_URL%/}/agent-install.sh" -o "$file"','bash "$file"'].join('; ');return 'PANEL_URL='+shellQuote(location.origin)+' HK_SDAN_TICKET='+shellQuote(ticket)+' bash -c '+shellQuote(script);}
function enrollment(token,ticket){if(ticket){const command=buildInstallCommand(ticket);modal(`<h2>一条命令接入 Debian VPS</h2><p>在目标服务器以 root 粘贴执行下面的完整命令，无需再次输入面板地址或密钥。</p><pre id="installCommand" class="install-command"></pre><button type="button" id="copyInstallCommand" class="primary">复制接入命令</button><p id="installCopyStatus" role="status"></p><p>凭证 10 分钟内有效，仅可成功使用一次。重新生成命令将使旧命令失效。成功兑换时会更换该服务器的采集密钥，因此请在对应的目标 VPS 上执行。</p><p>安装后约 30 秒开始显示数据。请勿将接入命令发给其他人；命令中不包含长期采集密钥。</p>`);$('installCommand').textContent=command;$('copyInstallCommand').onclick=async()=>{try{await navigator.clipboard.writeText(command);$('installCopyStatus').textContent='已复制，在目标 VPS 的 root 终端粘贴执行即可。';}catch(e){const range=document.createRange();range.selectNodeContents($('installCommand'));const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);$('installCopyStatus').textContent='已选中命令，请手动复制。';}};return;}
modal(`<h2>手动接入 Debian VPS</h2><p>在目标 VPS 上以 root 执行下面命令，再按提示输入面板地址和密钥。</p><pre>curl -fsS --proto '=https' ${esc(location.origin)}/agent-install.sh -o /tmp/hk-sdan-agent-install.sh\nbash /tmp/hk-sdan-agent-install.sh</pre><pre>${esc(location.origin)}</pre><pre class="token">${esc(token||'请重新生成接入命令')}</pre>`);}
async function generateInstallCommand(id){try{const result=await api('servers/'+id+'/install-ticket','POST');enrollment(null,result.ticket);}catch(e){notice(e.message);}}
function customerDnsSection(bindings){return `<section class="ip-history-panel client-dns-panel"><h2>IP 自动解析</h2><p>开启后，新公网 IP 会立即触发一次国内探测；所选探测节点全部通过后，自动更新这条 DNS 线路。</p>${bindings.length?bindings.map(b=>`<article class="client-dns-binding"><strong>${esc(b.rr)}.${esc(b.domain)} · ${esc(b.line)}</strong><p>解析 IP：${esc(b.expected_ip)}${b.candidate?` → ${esc(b.candidate)}`:''}<br>状态：${esc(b.status||'等待检查')}</p><button type="button" class="${b.automatic?'danger':'primary'}" data-client-dns-toggle="${b.id}" data-enabled="${b.automatic?1:0}">${b.automatic?'暂停自动解析':'开启自动解析'}</button><small>${b.verify_new_ip?'新 IP 需一次探测全部通过':'当前为直接解析模式'}</small></article>`).join(''):'<p>这台 VPS 尚未配置 DNS 绑定，请联系管理员完成域名和线路配置。</p>'}</section>`}
async function detail(id){const s=servers.find(s=>s.id===id);if(!s)return;try{let clientDNS=[];if(me.role==='admin')customers=await api('users');else clientDNS=(await api('client/servers/'+id+'/dns-bindings')).bindings;modal(`<small class="eyebrow">NETWORK CONNECTIONS</small><h2 style="font-size:24px;margin-top:15px">${esc(s.name)}</h2><p>${s.online?'在线':s.seen?'离线':'等待首次上报'} · ${s.seen?new Date(s.seen*1000).toLocaleString():'暂无数据'}</p><div class="uptime-reboot"><span>运行时间 <strong id="detailUptime">${formatUptime(s)}</strong></span><button id="detailReboot" class="reboot-button" ${canReboot(s)?'':'disabled'} title="${rebootReason(s)}">重启 VPS</button></div><p>${commandLabel(s.last_command)}</p><section class="ip-history-panel"><h2>公网 IP 历史</h2><div id="ipHistoryContent"><p>正在读取 IP 历史…</p></div></section>${me.role==='client'?customerDnsSection(clientDNS):''}<section class="bandwidth-panel"><div class="bandwidth-heading"><h2>带宽动态监控</h2><select id="networkRange" aria-label="带宽历史时间范围"><option value="1h">最近 1 小时</option><option value="24h">最近 24 小时</option></select></div><div id="bandwidthContent"><p>正在读取带宽数据…</p></div></section><div class="network-grid"><div><span>TCP 已建立连接</span><strong>${metric(s,'tcp')}</strong></div><div><span>UDP Socket</span><strong>${metric(s,'udp')}</strong></div></div><p>TCP：当前网络命名空间内 IPv4＋IPv6 的 ESTABLISHED socket 数。<br>UDP：新版客户端统计 IPv4＋IPv6 UDP socket，含监听及未连接 socket，与 ss -uanH 口径一致。旧客户端仍为 conntrack 会话，请升级。<br>${esc(s.metrics?.network_error||'')}<br>${s.online?'':'离线数据不作为当前实时数值展示。'}</p><p>主机：${esc(s.metrics?.hostname||'—')}<br>内核：${esc(s.metrics?.kernel||'—')}<br>运行时间：${s.online&&s.metrics?formatUptime(s):'—'}<br>累计网卡接收 / 发送：${s.online&&s.metrics?value(Math.round(s.metrics.rx_bytes/1048576),' MiB')+' / '+value(Math.round(s.metrics.tx_bytes/1048576),' MiB'):'—'}<br>累计网卡字节可能含虚拟网卡重复计量，并非商家计费流量。</p>${me.role==='admin'?`<label>分配给客户<select id="ownerSelect"><option value="">未分配</option>${customers.filter(c=>c.role==='client').map(c=>`<option value="${c.id}" ${s.owner_id===c.id?'selected':''}>${esc(c.username)}</option>`).join('')}</select></label><div class="detail-actions"><button id="saveOwner" class="primary">保存分配</button><button id="rotate">重置接入密钥</button><button id="remove" class="danger">移除服务器</button></div><p id="detailError"></p>`:''}`);startNetworkMonitor(id);$('detailReboot').onclick=()=>rebootServer(id);document.querySelectorAll('[data-client-dns-toggle]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api('client/dns-bindings/'+button.dataset.clientDnsToggle,'PATCH',{automatic:button.dataset.enabled!=='1'});await loadServers();await detail(id);notice(button.dataset.enabled==='1'?'已暂停 DNS 自动解析':'已开启：新 IP 一次探测通过后自动解析');}catch(e){button.disabled=false;notice(e.message);}});if(me.role==='admin'){$('saveOwner').onclick=async()=>{try{await api('servers/'+id,'PATCH',{owner_id:$('ownerSelect').value?Number($('ownerSelect').value):null});$('modal').close();await loadServers();notice('客户分配已保存')}catch(e){$('detailError').textContent=e.message}};$('rotate').onclick=async()=>{if(!confirm('重置后旧客户端会失去连接，需要使用新密钥重新接入，是否继续？'))return;try{const r=await api('servers/'+id+'/rotate','POST');enrollment(r.token,r.ticket)}catch(e){$('detailError').textContent=e.message}};$('remove').onclick=async()=>{if(!confirm('从面板移除此服务器及当前监控数据？不会卸载 VPS 上的客户端。'))return;try{await api('servers/'+id,'DELETE');$('modal').close();await loadServers()}catch(e){$('detailError').textContent=e.message}}}}catch(e){notice(e.message)}}
initializeEntry();

$('generatePassword').onclick=()=>{try{const input=$('customerPassword');input.value=generateCustomerPassword();input.type='text';$('passwordHint').textContent='随机密码已生成并显示，请复制保存后创建客户。';}catch(e){$('passwordHint').textContent='当前浏览器无法安全生成密码，请手动填写。';}};
$('copyPassword').onclick=async()=>{const input=$('customerPassword');if(!input.value){$('passwordHint').textContent='请先填写或生成密码。';return;}try{await navigator.clipboard.writeText(input.value);$('passwordHint').textContent='密码已复制，请妥善保存。';}catch(e){input.type='text';input.focus();input.select();$('passwordHint').textContent='自动复制不可用，已选中密码，请手动复制。';}};

async function copyCustomerValue(id,password){const customer=customers.find(c=>c.id===id);if(!customer)return;try{const credentials=password?await api('users/'+id+'/credentials','POST'):null;const text=password?credentials.password:customer.username;if(text===null){notice('旧客户的原密码无法还原，请点击“修改账号／密码”设置一次新密码。');return;}try{await navigator.clipboard.writeText(text);notice(password?'密码已复制':'账号已复制');}catch(e){modal('<h2>手动复制</h2><p>自动复制不可用，请复制下面已选中的内容。</p><input id="manualCopy" readonly aria-label="待复制内容">');$('manualCopy').value=text;$('manualCopy').focus();$('manualCopy').select();}}catch(e){notice(e.message);}}
async function viewCustomerPassword(id){try{const data=await api('users/'+id+'/credentials','POST');modal(`<h2>${esc(data.username)} · 登录密码</h2>${data.password===null?'<p>旧客户此前仅保存密码哈希，原密码无法还原。请先设置一次新密码，之后可随时查看和复制。</p>':'<label>当前密码<input id="viewCustomerSecret" readonly autocomplete="off"></label>'}<div class="detail-actions"><button id="editViewedCustomer" class="primary">修改账号／密码</button></div>`);if(data.password!==null)$('viewCustomerSecret').value=data.password;$('editViewedCustomer').onclick=()=>editCustomer(id);}catch(e){notice(e.message);}}
function editCustomer(id){const customer=customers.find(c=>c.id===id&&c.role==='client');if(!customer)return;modal(`<h2>修改客户账号／密码</h2><form id="editCustomerForm"><label>用户名<input name="username" id="editCustomerName" minlength="3" maxlength="64" required autocomplete="off"></label><label>新密码（留空则不修改）<input name="password" id="editCustomerPassword" type="password" minlength="12" maxlength="128" autocomplete="new-password"></label><button type="button" id="generateEditedPassword">生成随机密码</button><p>保存后该客户已有登录会失效，服务器分配保持不变。</p><button class="primary">保存修改</button><p id="editCustomerError" role="status"></p></form>`);$('editCustomerName').value=customer.username;$('generateEditedPassword').onclick=()=>{$('editCustomerPassword').value=generateCustomerPassword();$('editCustomerPassword').type='text';};$('editCustomerForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));if(!data.password)delete data.password;await api('users/'+id,'PATCH',data);$('modal').close();await loadUsers();notice('客户账号／密码已更新，可随时查看或复制密码。');}catch(e){$('editCustomerError').textContent=e.message;}finally{button.disabled=false;}};}
async function assignCustomerServers(id){const customer=customers.find(c=>c.id===id&&c.role==='client');if(!customer)return;try{const current=await api('servers');modal(`<h2>为 ${esc(customer.username)} 分配服务器</h2><p>勾选未分配的服务器进行分配；取消已勾选的服务器可解除分配。其他客户名下的服务器需先解除原分配。</p><form id="assignForm"><div class="assignment-list">${current.map(s=>`<label class="assignment-item"><input type="checkbox" name="server" value="${s.id}" ${s.owner_id===id?'checked':''} ${s.owner_id!==null&&s.owner_id!==id?'disabled':''}><span><strong>${esc(s.name)}</strong><small>${s.owner_id===id?'已分配给当前客户':s.owner_id===null?'未分配':'已分配给 '+esc(s.owner||'其他客户')}</small></span></label>`).join('')||'<p>还没有服务器，请先到“服务器”页面添加。</p>'}</div><div class="detail-actions"><button class="primary" ${current.length?'':'disabled'}>保存分配</button></div><p id="assignError" role="status"></p></form>`);$('assignForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;const selected=new Set(new FormData(e.target).getAll('server').map(Number));try{const changes=current.filter(s=>(s.owner_id===null&&selected.has(s.id))||(s.owner_id===id&&!selected.has(s.id)));for(const s of changes)await api('servers/'+s.id,'PATCH',{owner_id:selected.has(s.id)?id:null});$('modal').close();notice('服务器分配已保存');}catch(e){$('assignError').textContent='部分操作可能已保存：'+e.message+'。关闭后重新打开可查看当前分配。';}finally{button.disabled=false;}};}catch(e){notice(e.message);}}


function formatBytes(n){if(n==null)return '—';const units=['B','KiB','MiB','GiB','TiB'];let i=0;while(n>=1024&&i<units.length-1){n/=1024;i++;}return n.toLocaleString(undefined,{maximumFractionDigits:i?2:0})+' '+units[i];}
function formatRate(n){if(n==null)return '—';let i=0;const units=['bps','Kbps','Mbps','Gbps','Tbps'];while(n>=1000&&i<units.length-1){n/=1000;i++;}return n.toLocaleString(undefined,{maximumFractionDigits:i?2:0})+' '+units[i];}
function rateSum(key){const rows=scopedServers().filter(s=>s.online&&s.metrics?.[key]!=null);return rows.length?formatRate(rows.reduce((n,s)=>n+s.metrics[key],0)):'—';}
function trafficSum(key){const rows=scopedServers().filter(s=>s.traffic?.[key]!=null);return rows.length?formatBytes(rows.reduce((n,s)=>n+s.traffic[key],0)):'—';}
function stopNetworkMonitor(){clearInterval(networkTimer);networkTimer=null;networkServer=null;metricState=null;}
$('modal').addEventListener('close',()=>{stopNetworkMonitor();$('modalBody').replaceChildren();});
function startNetworkMonitor(id){stopNetworkMonitor();networkServer=id;networkRange='1h';$('networkRange').onchange=()=>{networkRange=$('networkRange').value;refreshNetwork();};refreshNetwork();networkTimer=setInterval(refreshNetwork,5000);}
async function refreshNetwork(){const id=networkServer,range=networkRange;if(id===null||!$('modal').open)return;try{const [d,ips]=await Promise.all([api('servers/'+id+'/network?range='+range),api('servers/'+id+'/ip-history')]);if(networkServer!==id||networkRange!==range||!$('modal').open)return;$('bandwidthContent').innerHTML=networkMarkup(d);$('ipHistoryContent').innerHTML=ipHistoryMarkup(ips);if($('detailUptime'))$('detailUptime').textContent=formatUptime({online:d.online,metrics:{uptime:d.uptime}});}catch(e){if(networkServer===id&&$('bandwidthContent'))$('bandwidthContent').textContent='读取失败：'+e.message;}}
function networkMarkup(d){const t=d.traffic;const values=d.points.flatMap(p=>[p.rx_bps,p.tx_bps]).filter(v=>v!=null);const max=Math.max(1,...values);const width=580,height=145,left=d.now-d.seconds;
 function pathFor(key){let path='',last=null;for(const p of d.points){const val=p[key];if(val==null){last=null;continue;}const x=Math.max(0,Math.min(width,(p.stamp-left)/d.seconds*width));const y=height-val/max*(height-12);path+=(last!==null&&p.stamp-last<=d.bucket*2?' L':' M')+x.toFixed(1)+' '+y.toFixed(1);last=p.stamp;}return path;}
 const line=values.length?`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="下载和上传带宽历史曲线"><path class="bandwidth-grid" d="M0 1H580M0 72H580M0 145H580"/><path class="rx-line" d="${pathFor('rx_bps')}"/><path class="tx-line" d="${pathFor('tx_bps')}"/></svg>`:'<p class="no-points">尚无带宽历史，需收到至少两次有效上报。</p>';
 return `<div class="bandwidth-now"><span>↓ 下行 <strong>${formatRate(d.rx_bps)}</strong></span><span>↑ 上行 <strong>${formatRate(d.tx_bps)}</strong></span></div><div class="chart-scale">${formatRate(max)}</div><div class="bandwidth-chart">${line}</div><div class="chart-times"><span>${new Date(left*1000).toLocaleTimeString()}</span><span>${new Date(d.now*1000).toLocaleTimeString()}</span></div><div class="traffic-grid"><div><small>今日接收 / 发送</small><strong>${formatBytes(t.today_rx)} / ${formatBytes(t.today_tx)}</strong></div><div><small>本月接收 / 发送</small><strong>${formatBytes(t.month_rx)} / ${formatBytes(t.month_tx)}</strong></div></div><p class="network-footnote">${d.online?'每 5 秒刷新；速率为上报区间的平均带宽。':'服务器离线，当前带宽不可用。'}<br>↓ 接收、↑ 发送均以 VPS 为视角。流量从启用统计后累计，按北京时间划分日期；非商家计费流量。<br>重启或计数器重置期间未观测到的流量无法补算，跨日区间按时间估算分摊。</p>`;}

function ipHistoryMarkup(data){const entries=data.events;return `${!data.available?'<p>当前客户端未上报公网 IP，请升级采集客户端。以下保留已记录的历史。</p>':''}${data.error?'<p>'+esc(data.error)+'</p>':''}${entries.length?`<div class="ip-current"><small>最近一次观测到的公网 IP</small><strong>${entries[0].addresses.length?entries[0].addresses.map(esc).join('<br>'):'未检测到网卡公网地址'}</strong></div><div class="ip-history-list">${entries.map((e,i)=>`<div class="ip-history-item"><time>${new Date(e.observed*1000).toLocaleString()}</time><span>${e.addresses.length?e.addresses.map(esc).join('<br>'):'未检测到网卡公网地址'}</span><small>${i===0?'最近记录':'历史记录'}</small></div>`).join('')}</div>`:'<p>暂无 IP 历史，接入新版客户端后开始记录。</p>'}<p class="network-footnote">优先记录新鲜的出口公网 IPv4／IPv6，没有出口结果时记录网卡公网地址。时间为面板首次观测到变化的时间；采集失败不会清空历史。不自动清理历史；此处显示最近 50 条，完整记录请从服务器列表的“历史 IP”查看。</p>`;}

function formatUptime(s){if(!s.online||s.metrics?.uptime==null)return '—';const seconds=Math.max(0,Math.floor(s.metrics.uptime));return Math.floor(seconds/86400)+' 天 '+Math.floor(seconds%86400/3600)+' 小时 '+Math.floor(seconds%3600/60)+' 分钟';}
function rebootPending(s){return s.last_command&&['queued','issued','accepted'].includes(s.last_command.status)&&Date.now()/1000-s.last_command.created<120;}
function canReboot(s){return s.online&&s.metrics?.capabilities?.includes('reboot')&&!rebootPending(s);}
function rebootReason(s){return !s.online?'服务器离线':!s.metrics?.capabilities?.includes('reboot')?'请先升级此服务器的客户端':rebootPending(s)?'已有重启任务':'正常重启系统，会中断现有连接';}
function commandLabel(command){if(!command)return '';return ({queued:'重启任务等待下发',issued:'重启任务已下发',accepted:'客户端已确认重启请求',completed:'已观测到系统重启',failed:'系统重启请求失败',expired:'重启任务已过期',cancelled:'分配变更，重启任务已取消',unconfirmed:'未确认系统是否完成重启'})[command.status]||'';}
async function rebootServer(id){const s=servers.find(s=>s.id===id);if(!s||!canReboot(s))return;if(!confirm('确定重启 '+s.name+' 吗？这会中断服务器上的所有现有连接和服务，等待系统重新启动。'))return;try{await api('servers/'+id+'/reboot','POST',{confirm:true});$('modal').close();await loadServers();notice('重启任务已提交，在线客户端将在下次上报时接收。请等待运行时间和在线状态更新。');}catch(e){notice(e.message);if($('modal').open)alert(e.message);}}

async function initializeEntry(){try{const info=await api('entry');$('loginTitle').textContent=info.kind==='admin'?'管理员登录':'客户登录';$('loginDesc').textContent=info.kind==='admin'?'HKSDAN 管理后台 · 请使用管理员账号':'查看和管理分配给你的服务器。';await boot();}catch(e){$('loginError').textContent=e.message;$('loginForm').hidden=true;}}
function updateEntryPreview(){$('entryPreview').textContent='管理员地址：'+location.origin+$('adminEntry').value;}
$('adminEntry').oninput=updateEntryPreview;
$('entryForm').onsubmit=async e=>{e.preventDefault();const path=$('adminEntry').value.trim();if(!confirm('将管理员入口改为 '+location.origin+path+'？旧入口将失效，管理员需要重新登录。请保存新地址。'))return;const button=e.submitter;button.disabled=true;try{const result=await api('settings','PATCH',{admin_path:path});if(result.changed){signout();location.assign(result.admin_path);}else notice('入口未变化');}catch(e){notice(e.message);}finally{button.disabled=false;}};


function ipAddressesMarkup(addresses){return addresses&&addresses.length?addresses.map(esc).join('<br>'):'未检测到网卡公网地址';}
async function showIPHistory(id){const node=servers.find(s=>s.id===id);if(!node)return;modal(`<h2>${esc(node.name)} · 历史 IP</h2><p>CMHK 重启更换 IP 后，仍通过固定接入密钥归属于同一台服务器。</p><div id="fullIPCurrent"></div><p id="fullIPSummary" role="status">正在读取…</p><div id="fullIPRows" class="full-ip-rows"></div><button id="loadMoreIP" type="button" hidden>加载更早记录</button><p class="network-footnote">变更时间为面板首次发现新 IP 的时间（北京时间），不是断网期间实际换 IP 的精确时刻。无变化不重复记录，采集失败不清空历史。优先记录新鲜的出口公网 IP，没有出口结果时记录网卡公网地址。</p>`);const view=ipHistoryView;let cursor=null,loaded=0,busy=false;
 async function load(){if(busy)return;busy=true;const button=$('loadMoreIP');button.disabled=true;try{const data=await api('servers/'+id+'/ip-history'+(cursor?'?before='+cursor:''));if(view!==ipHistoryView||!$('modal').open)return;loaded+=data.events.length;if(cursor===null){$('fullIPCurrent').innerHTML=data.current_addresses===null?'<p>暂无公网 IP 记录，请先升级并接入客户端。</p>':`<div class="ip-current"><small>最近观测到的公网 IP</small><strong>${ipAddressesMarkup(data.current_addresses)}</strong></div>`;}
 $('fullIPRows').insertAdjacentHTML('beforeend',data.events.map(event=>`<div class="full-ip-event"><div class="full-ip-event-head"><strong>${event.previous_addresses===null?'首次记录':'发现 IP 变化'}</strong><time>${new Date(event.observed*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}</time></div>${event.previous_addresses===null?'':`<div class="ip-transition"><small>更换前</small><span>${ipAddressesMarkup(event.previous_addresses)}</span></div>`}<div class="ip-transition"><small>${event.previous_addresses===null?'IP 地址':'更换后'}</small><span>${ipAddressesMarkup(event.addresses)}</span></div></div>`).join(''));
 $('fullIPSummary').textContent='已显示 '+loaded+' / '+data.total+' 条记录'+(!data.available?' · 当前客户端未上报 IP，请升级客户端':'')+(data.error?' · '+data.error:'');cursor=data.next_cursor;button.hidden=!data.has_more;button.textContent='加载更早记录';
 }catch(e){if(view===ipHistoryView&&$('modal').open){$('fullIPSummary').textContent='读取失败：'+e.message;button.hidden=false;button.textContent='重试';}}finally{busy=false;button.disabled=false;}}
 $('loadMoreIP').onclick=load;load();}

const metricNames={cpu:'CPU 使用率',memory:'内存使用率',network:'网络带宽',tcp:'TCP 连接数',udp:'UDP Socket 数'};
function openMetricWindow(id,key){const node=servers.find(s=>s.id===id);if(!node||!metricNames[key])return;modal(`<div class="metric-window"><small class="eyebrow">SERVER MONITOR</small><h2>${esc(node.name)}</h2><p>资源趋势与连接状态</p><div class="metric-tabs" role="tablist" aria-label="监控指标">${Object.entries(metricNames).map(([k,name])=>`<button type="button" role="tab" data-metric-tab="${k}" aria-selected="false">${name}</button>`).join('')}</div><div class="metric-toolbar"><span id="metricStatus" role="status">正在读取…</span><div class="metric-controls"><select id="metricRange" aria-label="历史时间范围"><option value="1h">最近 1 小时</option><option value="24h">最近 24 小时</option></select><button id="metricPause">暂停刷新</button><button id="metricRefresh">刷新</button></div></div><div id="metricWindowBody" role="tabpanel"></div><p class="network-footnote">每 5 秒刷新 · TCP／UDP 每 15 秒采集 · 历史每 15 秒保存 · 断报不连线</p></div>`);metricState={id,key,range:'1h',request:0,paused:false};$('metricRange').onchange=()=>{metricState.range=$('metricRange').value;refreshMetricWindow();};$('metricPause').onclick=()=>{if(!metricState)return;metricState.paused=!metricState.paused;$('metricPause').textContent=metricState.paused?'恢复刷新':'暂停刷新';if(!metricState.paused)refreshMetricWindow();};$('metricRefresh').onclick=()=>refreshMetricWindow();$('modalBody').querySelectorAll('[data-metric-tab]').forEach(button=>button.onclick=()=>{if(!metricState)return;metricState.key=button.dataset.metricTab;refreshMetricWindow();});refreshMetricWindow();networkTimer=setInterval(()=>{if(metricState&&!metricState.paused)refreshMetricWindow();},5000);}
async function refreshMetricWindow(){const state=metricState;if(!state||!$('modal').open)return;const key=state.key,range=state.range,serial=++state.request;$('modalBody').querySelectorAll('[data-metric-tab]').forEach(button=>button.setAttribute('aria-selected',String(button.dataset.metricTab===key)));$('metricWindowBody').setAttribute('aria-busy','true');try{const data=await api('servers/'+state.id+'/metrics?range='+range);if(metricState!==state||serial!==state.request||!$('modal').open)return;$('metricStatus').textContent=(data.online?'● 在线':'○ 离线')+' · 最后上报 '+(data.seen?new Date(data.seen*1000).toLocaleTimeString():'暂无');$('metricWindowBody').innerHTML=monitorMarkup(data,key);bindMonitorChart(data,key);}catch(e){if(metricState===state&&serial===state.request&&$('modal').open){$('metricStatus').textContent='读取失败：'+e.message;$('metricWindowBody').textContent='无法取得当前数据，请稍后重试。';}}finally{if(metricState===state&&serial===state.request&&$('metricWindowBody'))$('metricWindowBody').setAttribute('aria-busy','false');}}
function monitorSeries(key){return key==='network'?[{key:'rx_bps',name:'↓ 下行',color:'#007aff'},{key:'tx_bps',name:'↑ 上行',color:'#30b989'}]:[{key,name:metricNames[key],color:{cpu:'#007aff',memory:'#9b6bea',tcp:'#e89a28',udp:'#30b989'}[key]}];}
function monitorFormat(key,n){return n==null?'—':key==='network'?formatRate(n):key==='cpu'||key==='memory'?Number(n).toFixed(1)+'%':Math.round(n).toLocaleString();}
function monitorMarkup(data,key){const series=monitorSeries(key),format=n=>monitorFormat(key,n),percent=key==='cpu'||key==='memory',start=data.now-data.seconds,width=720,height=220,values=data.points.flatMap(p=>series.map(s=>p[s.key])).filter(Number.isFinite),max=percent?100:Math.max(1,...values)*1.1;
const cards=series.map(s=>{const vals=data.points.map(p=>p[s.key]).filter(Number.isFinite),current=key==='network'?data[s.key]:data.current[{cpu:'cpu_percent',memory:'memory_percent',tcp:'tcp',udp:'udp'}[key]];return `<div class="monitor-stat" style="--metric-color:${s.color}"><small>${s.name}</small><strong>${format(current)}</strong><div><span>区间平均 <b>${format(vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null)}</b></span><span>区间峰值 <b>${format(vals.length?Math.max(...vals):null)}</b></span></div></div>`;}).join('');
let plots='';for(const line of series){let segment=[],prev=null;const flush=()=>{if(!segment.length)return;const path=segment.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' ');plots+=`<path d="${path} L${segment.at(-1)[0]} ${height} L${segment[0][0]} ${height} Z" fill="${line.color}" opacity=".07"/><path d="${path}" fill="none" stroke="${line.color}" stroke-width="2.2" vector-effect="non-scaling-stroke"/>`+segment.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="2" fill="${line.color}"/>`).join('');segment=[];};for(const p of data.points){if(!Number.isFinite(p[line.key])){flush();prev=null;continue;}if(prev!==null&&p.stamp-prev>data.bucket*2)flush();segment.push([Math.max(0,Math.min(width,(p.stamp-start)/data.seconds*width)).toFixed(2),(height-p[line.key]/max*(height-8)).toFixed(2)]);prev=p.stamp;}flush();}
const labels=Array.from({length:5},(_,i)=>`<span>${new Date((start+data.seconds*i/4)*1000).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</span>`).join('');
const note={cpu:'CPU 使用率来自相邻两次客户端采样。',memory:'内存使用率按 MemAvailable 计算。',network:'↓ 接收、↑ 发送以 VPS 为视角；带宽为采样区间平均值。',tcp:'TCP 统计 IPv4＋IPv6 的 ESTABLISHED socket，不是每秒新建连接。',udp:'UDP 为 IPv4＋IPv6 socket 数，包含监听及未连接 socket，与 ss -uanH 口径一致；旧客户端需升级。'}[key];
return `<div class="monitor-stats">${cards}</div><div class="monitor-plot"><div class="monitor-axis"><span>${format(max)}</span><span>${format(max/2)}</span><span>${format(0)}</span></div><div class="monitor-canvas">${values.length?`<svg id="monitorSVG" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="${metricNames[key]}历史曲线"><path d="M0 1H720M0 110H720M0 220H720" stroke="#e7ebf2" stroke-dasharray="4 5" fill="none"/>${plots}<line id="monitorCursor" y1="0" y2="220" stroke="#8b95a5" stroke-dasharray="3 4" visibility="hidden"/></svg>`:'<div class="monitor-empty">暂无历史数据，等待客户端上报</div>'}<div id="monitorTooltip" class="monitor-tooltip" role="status" hidden></div></div></div><div class="monitor-times">${labels}</div><p class="network-footnote">${note}<br>${data.seconds>3600?'24 小时按 6 分钟平均值聚合':'最近 1 小时按 15 秒时间桶聚合'}；区间平均及峰值按可见聚合点计算。${!data.online?'服务器离线，当前值不可用。':''}</p>${key==='network'?`<div class="traffic-grid"><div><small>今日接收 / 发送</small><strong>${formatBytes(data.traffic?.today_rx)} / ${formatBytes(data.traffic?.today_tx)}</strong></div><div><small>本月接收 / 发送</small><strong>${formatBytes(data.traffic?.month_rx)} / ${formatBytes(data.traffic?.month_tx)}</strong></div></div><p class="network-footnote">按北京时间统计，自启用后累计，非商家计费流量。</p>`:''}`;}
function bindMonitorChart(data,key){const svg=$('monitorSVG');if(!svg)return;const tip=$('monitorTooltip'),cursor=$('monitorCursor'),series=monitorSeries(key);function show(event){const rect=svg.getBoundingClientRect(),fraction=Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width)),stamp=data.now-data.seconds+fraction*data.seconds;const point=data.points.reduce((best,p)=>!best||Math.abs(p.stamp-stamp)<Math.abs(best.stamp-stamp)?p:best,null);if(!point||Math.abs(point.stamp-stamp)>data.bucket*2){tip.hidden=true;cursor.setAttribute('visibility','hidden');return;}const x=Math.max(0,Math.min(720,(point.stamp-(data.now-data.seconds))/data.seconds*720));cursor.setAttribute('x1',x);cursor.setAttribute('x2',x);cursor.setAttribute('visibility','visible');tip.innerHTML=`<time>${new Date(point.stamp*1000).toLocaleString()}</time>`+series.map(s=>`<div style="color:${s.color}">${s.name} <b>${monitorFormat(key,point[s.key])}</b></div>`).join('');tip.hidden=false;tip.style.left=Math.max(0,Math.min(rect.width-190,fraction*rect.width+12))+'px';}svg.onpointermove=show;svg.onpointerdown=show;svg.onpointerleave=()=>{tip.hidden=true;cursor.setAttribute('visibility','hidden');};}

function publicIPMarkup(s){const m=s.metrics||{},fresh=s.online&&m.egress_checked&&Date.now()/1000-m.egress_checked<=90;const addresses=fresh&&m.egress_ips?.length?m.egress_ips:m.public_ips;return `<span class="muted server-ip">公网 IP：${addresses?.length?esc(addresses.join(' · ')):'待采集'}</span>`;}

async function copyCustomerInfo(id){if(me?.role!=='admin')return;try{const data=await api('users/'+id+'/credentials','POST');if(data.password===null){notice('旧客户的原密码无法还原，请先点击“修改账号／密码”设置新密码，再复制客户信息。');return;}const text=`账号：${data.username}\n密码：${data.password}\n登录网站：${location.origin}/`;try{await navigator.clipboard.writeText(text);notice('客户信息已复制（账号、密码、登录网站）');}catch(e){modal('<h2>复制客户信息</h2><p>自动复制不可用，请复制下面已选中的内容。</p><textarea id="manualCustomerInfo" rows="5" readonly autocomplete="off" aria-label="客户登录信息" style="width:100%;resize:vertical"></textarea>');$('manualCustomerInfo').value=text;$('manualCustomerInfo').focus();$('manualCustomerInfo').select();}}catch(e){notice(e.message);}}
